-- ---------------------------------------------------------------------
-- 2_data.sql — the rows the application needs, plus captured job data
--
--   mysqlsh --sql -u root -p -h localhost --file 2_data.sql
--
-- Run after 1_structure.sql. Contains:
--
--   admin              2 accounts (admin / 123, and the "system" account
--                      log_entry falls back to when no one is signed in)
--   provider_profile   LinkedIn and Indeed, with the corrected required
--                      fields -- LinkedIn needs only `location`; Indeed
--                      needs `country`, `domain`, `location`
--   scraper            2 working scrapers, already configured
--   job_listing        20 real listings captured from the providers
--   log_entry          22 activity entries from those runs
--   job_enrichment     the LLM extractions and embeddings for those 20
--                      listings, so matching works immediately
--
-- ENRICHMENT IS INCLUDED. A fresh install needs no OpenAI calls to have
-- working matches -- upload a CV and you get a ranked list straight away.
-- After scraping new listings, regenerate with:
--
--   python enrich_jobs.py
--   python refresh_enrichment_data.py
--
-- GENERATED vs HAND-MAINTAINED. Three sections of this file are produced by
-- that script and are marked with `>>> BEGIN <table>` / `<<< END <table>`:
-- job_listing, log_entry and job_enrichment. Edit them and your next run
-- overwrites the edit. Everything else -- admin, provider_profile, scraper,
-- the DELETE block, this header -- is hand-maintained and the script does
-- not touch it. That split is why there is a script at all: a plain
-- `mysqldump` over the whole file would flatten the commented, column-named
-- INSERTs below into positional tuples and lose every explanation with them.
--
-- The three generated tables are regenerated TOGETHER, and must be.
-- job_enrichment.job_listing_id is a foreign key to job_listing.id, and
-- FOREIGN_KEY_CHECKS is back on before any INSERT below runs. Refreshing
-- the enrichment without the listings it references produces a file that
-- restores on the machine it came from and fails on a clean install.
--
-- SAFE TO RE-RUN, BUT DESTRUCTIVE. Every table it fills is cleared first,
-- so rows are replaced rather than duplicated. Note the third line below:
-- job_listing has ON DELETE CASCADE from job_enrichment and job_match, so
-- clearing listings would silently take the enrichment with it. Those two
-- deletes are written out explicitly rather than left to the cascade, so
-- the cost is visible in the file rather than hidden in the schema.
--
-- What re-running does cost you: job_match is cleared, so every jobseeker's
-- stored ranking is discarded and has to be recomputed on their next upload.
-- That is free -- matching makes no API calls -- but it is not nothing.
-- ---------------------------------------------------------------------

USE cvision;

-- Children first. job_match and job_enrichment would be removed anyway by
-- the cascade from job_listing; deleting them here makes that explicit.
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM job_match;
DELETE FROM job_enrichment;
DELETE FROM log_entry;
DELETE FROM job_listing;
DELETE FROM schedule;
DELETE FROM scraper;
DELETE FROM provider_profile;
DELETE FROM admin;
SET FOREIGN_KEY_CHECKS = 1;


-- Admin accounts --------------------------------------------------------
-- The "system" row exists because log_service falls back to user_id
-- "system" for anything with no signed-in admin (an auto-run firing before
-- login), and log_entry.user_id is a foreign key to admin.id.
-- The password is plaintext: authentication is Feature 5 and the login gate
-- is a local-development stand-in. Change both before this is reachable by
-- anyone else.
INSERT INTO `admin` VALUES ('a1b2c3d4-0000-4000-8000-000000000001','admin','123'),('system','system','!');


